package dev.pocketengine.features.memory;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.concurrent.atomic.AtomicInteger;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

/** Original atomic Book/closed native archive lineage. Unknown offline history is not a grant,
 * and current known source/record withdrawal cannot be washed by an imported new record id. */
public final class MemoryArchiveCurrentnessTest {
    @Rule public final TemporaryFolder temporary=new TemporaryFolder();
    private static final String SECRET="KNOWN_FORGOTTEN_NATIVE_ARCHIVE_BODY_836";
    private static JSONObject owner()throws Exception{return new JSONObject().put("ownerId","owner").put("spaceId","private");}
    private static JSONObject record(String text)throws Exception{return new JSONObject().put("text",text).put("source","主人明确保存");}
    private static SourceRef source(){return new SourceRef("message","native-original-message",1,"owner","private");}
    private MemoryBook book(File file)throws Exception{return new MemoryBook(file,(scope,kind,id)->new SourceRef.State(source(),false));}
    @Test public void knownNativeSourceForgetBeforeImportDoesNotReintroduceArchiveBody()throws Exception{
        File file=new File(temporary.newFolder(),"original-book.json");MemoryBook book=book(file);JSONObject original=book.save(owner(),record(SECRET).put("sourceRefs",new JSONArray().put(source().toJson())),1);JSONObject archive=book.ownerArchive(owner());book.forget(owner(),original.getString("id"));book.restoreOwnerArchive(owner(),archive,"known:source-before");assertFalse("new archive id reintroduced a known forgotten original",book.list(owner()).toString().contains(SECRET));assertFalse(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8).contains(SECRET));
    }
    @Test public void knownNativeDeletionAfterImportRetiresThePassiveAliasBody()throws Exception{
        java.util.concurrent.atomic.AtomicBoolean deleted=new java.util.concurrent.atomic.AtomicBoolean();MemoryBook book=new MemoryBook(new File(temporary.newFolder(),"original-book.json"),(scope,kind,id)->new SourceRef.State(source(),deleted.get()));book.save(owner(),record(SECRET).put("sourceRefs",new JSONArray().put(source().toJson())),1);JSONObject archive=book.ownerArchive(owner());book.restoreOwnerArchive(owner(),archive,"known:source-after");deleted.set(true);book.sourceDeleted(owner(),source());assertFalse("archive-only is not a current body barrier",book.list(owner()).toString().contains(SECRET));assertFalse(book.ownerArchive(owner()).toString().contains(SECRET));
    }
    @Test public void exactNativeManualRecordForgetCannotBeWashedByNewArchiveId()throws Exception{
        MemoryBook book=new MemoryBook(new File(temporary.newFolder(),"original-book.json"));JSONObject original=book.save(owner(),record(SECRET),1),archive=book.ownerArchive(owner());book.forget(owner(),original.getString("id"));book.restoreOwnerArchive(owner(),archive,"known:manual-before");assertFalse("exact original manual record was forgotten, not an unknown remote source",book.list(owner()).toString().contains(SECRET));
    }
    @Test public void freshOfflineTargetWithoutLaterEvidenceKeepsUnknownReadOnlyArchiveAndNoSourceAuthority()throws Exception{
        MemoryBook source=book(new File(temporary.newFolder(),"source-book.json"));source.save(owner(),record(SECRET).put("sourceRefs",new JSONArray().put(source().toJson())),1);JSONObject archive=source.ownerArchive(owner());AtomicInteger resolutions=new AtomicInteger();MemoryBook fresh=new MemoryBook(new File(temporary.newFolder(),"target-book.json"),(scope,kind,id)->{resolutions.incrementAndGet();throw new AssertionError("offline restore cannot mint or resolve source authority");});JSONObject result=fresh.restoreOwnerArchive(owner(),archive,"unknown:offline");assertEquals(0,result.getInt("formalMemoryActivated"));JSONObject row=fresh.list(owner()).getJSONObject(0);assertEquals(SECRET,row.getString("text"));assertTrue(row.getBoolean("archiveOnly"));assertFalse(row.getBoolean("active"));assertEquals(0,fresh.search(owner(),SECRET,16).length());assertEquals(0,resolutions.get());
    }
    @Test public void carriedOriginalSourceBarrierSuppressesHistoricalBodyOnAnOfflineTarget()throws Exception{
        MemoryBook source=book(new File(temporary.newFolder(),"source-book.json"));JSONObject original=source.save(owner(),record(SECRET).put("sourceRefs",new JSONArray().put(source().toJson())),1),old=source.ownerArchive(owner());source.forget(owner(),original.getString("id"));JSONObject later=source.ownerArchive(owner());
        // A legacy closed archive can retain historical rows alongside its later exact source
        // evidence. Hash/count validation is not permission to ignore that negative evidence.
        JSONObject carried=new JSONObject(old.toString()).put("sources",later.getJSONArray("sources"));carried.put("counts",MemoryArchive.counts(carried));carried.put("sectionDigest",MemoryArchive.sectionDigest(carried));MemoryArchive.checked(carried,owner());MemoryBook fresh=new MemoryBook(new File(temporary.newFolder(),"target-book.json"));fresh.restoreOwnerArchive(owner(),carried,"carried:source");assertFalse(fresh.list(owner()).toString().contains(SECRET));
    }
    @Test public void reexportedArchiveLineageDoesNotHideAnExactLocallyForgottenOriginal()throws Exception{
        MemoryBook source=book(new File(temporary.newFolder(),"source-book.json"));JSONObject original=source.save(owner(),record(SECRET).put("sourceRefs",new JSONArray().put(source().toJson())),1),old=source.ownerArchive(owner());MemoryBook hop=new MemoryBook(new File(temporary.newFolder(),"hop-book.json"));hop.restoreOwnerArchive(owner(),old,"first:hop");JSONObject nested=hop.ownerArchive(owner());source.forget(owner(),original.getString("id"));source.restoreOwnerArchive(owner(),nested,"second:hop");assertFalse("closed archive lineage was flattened into a clean new id",source.list(owner()).toString().contains(SECRET));
    }
    @Test public void survivingAncestorsKeepTheirOriginalBodiesButCannotRegenerateTheForgottenConclusion()throws Exception{
        MemoryBook book=new MemoryBook(new File(temporary.newFolder(),"original-book.json"));JSONObject a=book.save(owner(),record("保留原始理由甲"),1),b=book.save(owner(),record("保留原始理由乙"),2);JSONArray refs=new JSONArray().put(new JSONObject().put("id",a.getString("id")).put("revision",1)).put(new JSONObject().put("id",b.getString("id")).put("revision",1));JSONObject draft=book.proposeConsolidation(owner(),new JSONObject().put("text",SECRET).put("layer","fact").put("reason","两个已选原始依据").put("applicability",""),refs,3);JSONObject summary=book.acceptCandidate(owner(),draft.getString("id"),1,4).getJSONObject("record"),archive=book.ownerArchive(owner());book.forget(owner(),summary.getString("id"));book.restoreOwnerArchive(owner(),archive,"ancestor:unchanged");assertEquals("保留原始理由甲",book.get(owner(),a.getString("id")).getString("text"));assertEquals("保留原始理由乙",book.get(owner(),b.getString("id")).getString("text"));assertFalse(book.list(owner()).toString().contains(SECRET));assertEquals(2,book.search(owner(),"保留原始理由",16).length());
    }
    @Test public void fullExistingTombstoneBoundRefusesTheNextForgetWithoutEvictingOldProtection()throws Exception{
        File file=new File(temporary.newFolder(),"original-book.json");MemoryBook first=new MemoryBook(file);JSONObject forgotten=first.save(owner(),record(SECRET),1),archive=first.ownerArchive(owner());first.forget(owner(),forgotten.getString("id"));JSONObject stored=new JSONObject(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));JSONArray fences=stored.getJSONArray("recordForgetBarriers");JSONObject nativeTemplate=fences.getJSONObject(0);while(fences.length()<1000)fences.put(new JSONObject(nativeTemplate.toString()).put("recordId",java.util.UUID.randomUUID().toString()));Files.write(file.toPath(),stored.toString().getBytes(StandardCharsets.UTF_8));MemoryBook full=new MemoryBook(file);JSONObject live=full.save(owner(),record("达到屏障边界时保留当前数据"),2);String before=new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);assertThrows(IllegalStateException.class,()->full.forget(owner(),live.getString("id")));assertEquals(before,new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));MemoryBook cold=new MemoryBook(file);assertEquals(live.getString("id"),cold.get(owner(),live.getString("id")).getString("id"));assertEquals(1000,cold.ownerArchive(owner()).getJSONArray("recordForgetBarriers").length());cold.restoreOwnerArchive(owner(),archive,"full:old-known");assertFalse(cold.list(owner()).toString().contains(SECRET));assertEquals(1000,new JSONObject(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8)).getJSONArray("recordForgetBarriers").length());
    }
    @Test public void newerNativeSourceVersionWithoutDeletionKeepsHistoricalArchiveOnlyBody()throws Exception{
        java.util.concurrent.atomic.AtomicReference<SourceRef.State> current=new java.util.concurrent.atomic.AtomicReference<>(new SourceRef.State(source(),false));MemoryBook book=new MemoryBook(new File(temporary.newFolder(),"original-book.json"),(scope,kind,id)->current.get());book.save(owner(),record(SECRET).put("sourceRefs",new JSONArray().put(source().toJson())),1);JSONObject archive=book.ownerArchive(owner());SourceRef newer=new SourceRef(source().kind,source().sourceId,2,"owner","private");current.set(new SourceRef.State(newer,false));book.sourceUpdated(owner(),newer);book.restoreOwnerArchive(owner(),archive,"historical:not-deleted");assertEquals(SECRET,book.list(owner()).getJSONObject(0).getString("text"));assertTrue(book.list(owner()).getJSONObject(0).getBoolean("archiveOnly"));assertEquals(0,book.search(owner(),SECRET,16).length());
    }
    @Test public void laterNativeRevisionCannotWashTheKnownDeletionFloorOfTheSameOriginalKey()throws Exception{
        File file=new File(temporary.newFolder(),"original-book.json");java.util.concurrent.atomic.AtomicReference<SourceRef.State> current=new java.util.concurrent.atomic.AtomicReference<>(new SourceRef.State(source(),false));MemoryBook book=new MemoryBook(file,(scope,kind,id)->current.get());book.save(owner(),record(SECRET).put("sourceRefs",new JSONArray().put(source().toJson())),1);JSONObject archive=book.ownerArchive(owner());current.set(new SourceRef.State(source(),true));book.sourceDeleted(owner(),source());SourceRef newer=new SourceRef(source().kind,source().sourceId,2,"owner","private");current.set(new SourceRef.State(newer,false));book.sourceUpdated(owner(),newer);book.save(owner(),record("原生新版本明确保留的新内容").put("sourceRefs",new JSONArray().put(newer.toJson())),2);book.restoreOwnerArchive(owner(),archive,"deleted:then-new-native-version");assertFalse(book.list(owner()).toString().contains(SECRET));assertEquals("原生新版本明确保留的新内容",book.search(owner(),"明确保留的新内容",16).getJSONObject(0).getString("text"));assertFalse(new MemoryBook(file).list(owner()).toString().contains(SECRET));
    }
    @Test public void failedAtomicForgetKeepsTheOriginalRowsAndDoesNotPublishAnUncommittedBarrier()throws Exception{
        File file=new File(temporary.newFolder(),"original-book.json");MemoryBook book=book(file);JSONObject original=book.save(owner(),record(SECRET).put("sourceRefs",new JSONArray().put(source().toJson())),1),archive=book.ownerArchive(owner());book.restoreOwnerArchive(owner(),archive,"atomic:alias");String before=new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);File blocked=new File(file+".new");assertTrue(blocked.mkdir());assertThrows(java.io.IOException.class,()->book.forget(owner(),original.getString("id")));assertEquals(before,new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));assertEquals(2,book.list(owner()).length());assertTrue(blocked.delete());book.forget(owner(),original.getString("id"));assertFalse(book.list(owner()).toString().contains(SECRET));assertFalse(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8).contains(SECRET));assertEquals(0,book.ownerArchiveRestoration(owner(),"atomic:alias").getInt("currentlyReadableRecords"));
    }
    @Test public void coldLegacyAliasWithAlreadyPersistedNativeDeletionIsRetiredWithoutNewAuthority()throws Exception{
        File file=new File(temporary.newFolder(),"original-book.json");java.util.concurrent.atomic.AtomicBoolean deleted=new java.util.concurrent.atomic.AtomicBoolean();MemoryBook book=new MemoryBook(file,(scope,kind,id)->new SourceRef.State(source(),deleted.get()));book.save(owner(),record(SECRET).put("sourceRefs",new JSONArray().put(source().toJson())),1);JSONObject archive=book.ownerArchive(owner());book.restoreOwnerArchive(owner(),archive,"cold:legacy");JSONObject before=new JSONObject(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));JSONArray aliases=new JSONArray();for(int i=0;i<before.getJSONArray("records").length();i++){JSONObject row=before.getJSONArray("records").getJSONObject(i);if(row.optBoolean("archiveOnly"))aliases.put(row);}deleted.set(true);book.sourceDeleted(owner(),source());JSONObject committedNegative=new JSONObject(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));
        // Reconstruct the old closed native shape: it retained only the passive alias alongside
        // the exact already committed original deletion; no arbitrary source/native flag is used.
        committedNegative.put("records",aliases);Files.write(file.toPath(),committedNegative.toString().getBytes(StandardCharsets.UTF_8));MemoryBook cold=new MemoryBook(file);assertFalse(cold.list(owner()).toString().contains(SECRET));assertFalse(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8).contains(SECRET));JSONObject receipt=cold.ownerArchiveRestoration(owner(),"cold:legacy");assertEquals(0,receipt.getInt("currentlyReadableRecords"));assertEquals(0,receipt.getInt("formalMemoryActivated"));assertFalse(receipt.getBoolean("executionAuthorized"));
    }
    @Test public void archiveEvidenceWithoutItsExactNativeImportMappingCannotInventAnAncestor()throws Exception{
        File file=new File(temporary.newFolder(),"original-book.json");MemoryBook nativeBook=book(file);JSONObject known=nativeBook.save(owner(),record(SECRET).put("sourceRefs",new JSONArray().put(source().toJson())),1),knownArchive=nativeBook.ownerArchive(owner());nativeBook.forget(owner(),known.getString("id"));MemoryBook unrelated=new MemoryBook(new File(temporary.newFolder(),"unrelated-book.json"));unrelated.save(owner(),record("未关联的档案数据"),1);JSONObject forged=unrelated.ownerArchive(owner()),row=forged.getJSONArray("records").getJSONObject(0),claimed=new JSONObject(known.toString());claimed.remove("text");row.put("archiveOnly",true).put("formation","archive_restore").put("core",false).put("sourceIds",new JSONArray()).put("sourceRefs",new JSONArray()).put("importedFrom",new JSONObject().put("archiveImportId","not:an-original-import").put("originalId",known.getString("id")).put("sectionDigest",knownArchive.getString("sectionDigest")).put("originalType","record")).put("archiveEvidence",new JSONObject().put("originalType","record").put("original",claimed));forged.put("counts",MemoryArchive.counts(forged));forged.put("sectionDigest",MemoryArchive.sectionDigest(forged));String before=new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);assertThrows(SecurityException.class,()->nativeBook.restoreOwnerArchive(owner(),forged,"unproven:ancestor"));assertEquals(before,new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));
    }
}
